#!/usr/bin/env python3
"""
Leerie — deterministic task orchestrator for Claude Code.

Runs entirely on the Claude Code CLI / subscription. Every unit of LLM work is
a `claude -p` headless invocation. This script owns ALL control flow — phase
sequencing, wave scheduling, caps, retries, integration — in real Python, so
the orchestration cannot drift the way an LLM-driven controller can.

Each worker is a separate `claude -p` process, so there is no subagent nesting
anywhere. The script is the orchestrator; each `claude -p` call is a leaf.

Usage:
    leerie "<task description>"
    leerie resume
    leerie "<task>" --answers answers.json
    leerie "<task>" --clarify             # opt into surfacing intent questions

Run it from the root of the target git repository.
"""
from __future__ import annotations

import argparse
import asyncio
import concurrent.futures
import contextlib
import copy
import ctypes
import errno
import fcntl
import functools
import hashlib
import json
import os
import re
import shlex
import shutil
import signal
import socket
import stat
import subprocess
import sys
import time
import urllib.error
import urllib.request
import uuid
import weakref
from collections import deque
from collections.abc import Awaitable, Callable, Iterator
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import TextIO
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

# tenacity is imported lazily inside claude_p() (its sole use site), not at
# module scope, so orchestrator/leerie.py loads on a bare host python3 that
# lacks requirements.txt deps. The `config --recapture` host seam
# (leerie:864) exec_module()s this file on the host, where python3 is not
# guaranteed to have tenacity; a module-scope import there would crash before
# run_recapture_deps()'s pathlib guards can print their diagnostic. Do not
# hoist it back to the top.

ROOT = Path(__file__).resolve().parent.parent       # leerie plugin/repo root
PROMPTS = ROOT / "prompts"
SCRIPTS = ROOT / "scripts"


def _read_version() -> str:
    """Single source of truth: `.claude-plugin/plugin.json`'s `version`
    field. Read at every `main()` invocation (the f-string in the
    `version` action evaluates eagerly), not at import time. The
    manifest is part of the distributed plugin, so a missing /
    malformed file means the install is broken and a clear runtime
    error is the right outcome."""
    return json.loads(
        (ROOT / ".claude-plugin" / "plugin.json").read_text()
    )["version"]

# `{{include: _foo.md}}` placeholder pattern used by _load_prompt() to embed
# a shared prompt fragment into a worker prompt. Only files prefixed with
# `_` are eligible — that prefix marks an internal include, never a
# standalone worker prompt. One level deep; no recursion needed today.
_PROMPT_INCLUDE_RE = re.compile(r"\{\{\s*include:\s*(_[a-z0-9_]+\.md)\s*\}\}")


def _load_prompt(name: str) -> str:
    """Read prompts/<name>.md and expand any {{include: _foo.md}}
    placeholders by inlining the named fragment. Replaces the prior
    `(PROMPTS / f"{name}.md").read_text()` pattern so the
    clarification-filter wording can live in one place
    (prompts/_clarification_filter.md, included by both the classifier
    and the implementer prompts). See DESIGN.md §11."""
    raw = (PROMPTS / f"{name}.md").read_text()
    return _PROMPT_INCLUDE_RE.sub(
        lambda m: (PROMPTS / m.group(1)).read_text(), raw)

# Minimum `claude` CLI version that supports `--json-schema` in `claude -p`
# mode. Anthropic CHANGELOG v2.1.22 (2026-01-28): "Fixed structured outputs
# for non-interactive (-p) mode." Earlier 2.1.x point releases may work but
# have no positive evidence in the release notes; v1.x and v2.0.x do not
# have the flag at all. Enforced at preflight by _check_claude_cli_version().
MIN_CLAUDE_CLI = (2, 1, 22)

# --- tunable caps --------------------------------------------------------
DEFAULT_CAPS = {
    # Runaway backstop, not a routine capacity limit (N3+N4, corpus-derived
    # 2026-08-09): the 8 per-subtask retry caps already catch looping
    # runaways locally; this global ceiling only needs to stay above the
    # cost of a legitimate large plan. Measured worst case 27.0 calls/
    # completed-subtask, median ~17.5 -- 2000 covers ~74 subtasks at the
    # worst observed rate and ~115 at the median while remaining a genuine
    # backstop for a run that has actually gone wrong.
    "max_total_workers": 2000,      # hard ceiling on claude -p invocations
    # Share of max_total_workers that recursive decomposition (fit_judge +
    # splitter, DESIGN §5½ (P1)) may spend before it is forced to stop
    # splitting and accept remaining nodes as leaves (N3+N4). It partitions
    # the shared worker budget (State.bump_workers) so decomposition cannot
    # starve execution before a single line of code is written.
    #
    # **This is a runaway backstop, not a tuned threshold.** At the current
    # max_total_workers it trips at 0.40 * 2000 = 800 decomposition calls,
    # and the worst run in a 143-run corpus spent 348 -- so it fires on 0 of
    # 143. Do not read the 40% as calibrated against observed runs: the
    # corpus separation the figure came from (decomposition share of a run's
    # REALIZED spend) is a post-hoc measure, and applying it to the CAP is a
    # different quantity that N4's 200 -> 2000 raise multiplied by ten.
    #
    # The observed failure it was written for is addressed by that raise
    # alone: of the 24 runs that ever hit the old 200 cap, the 22 with
    # telemetry spent at most 467 calls total (none approaches 2000) and 20
    # of 22 spent under 40% of their calls on decomposition (p50 13%).
    #
    # Two live-gate designs were measured against the corpus and rejected.
    # Share-of-realized-spend cannot be evaluated during planning, when the
    # denominator is still tiny -- it crosses 0.40 at ~7 calls and would
    # refuse healthy runs (p50 13). Calls-per-leaf separates poorly (K=3:
    # 10% of healthy vs 7% of unhealthy) and is survivor-biased, since a run
    # that dies during planning never writes the plan.json its leaf count
    # would come from -- exactly the population at issue.
    # `_warn_decomposition_share` records the share at plan completion so a
    # future threshold can be derived from unbiased data.
    #
    # It does NOT gate on fit_judge score (that option -- stopping early on
    # projected cost -- was investigated and rejected: it would ship exactly
    # the low-scoring nodes decompose_fit_threshold exists to keep
    # splitting).
    "decompose_budget_share": 0.40,
    # Concurrent workers within a wave. Per-worker cgroup containment
    # (DESIGN §6 *Memory containment*) keeps an OOM inside one worker's
    # cgroup, so wave-level parallelism can be high without cascading to
    # sshd / lima-guestagent. Users on smaller VMs can opt down via
    # --max-parallel.
    "max_parallel": 5,              # concurrent workers within a wave
    # Per-subtask re-spawn budget. Consumed by BOTH context-exhaustion
    # handoffs and DESIGN §11 mid-execution clarifications — a subtask
    # that mixes the two is still bounded by this single cap, so "ask
    # instead of research" cannot win extra budget. See DESIGN §11
    # mid-execution clarification subsection.
    "subtask_continuations": 3,
    "failed_retries": 1,            # re-spawns of a failed implementer
    # Orchestrator-level conformer re-runs per subtask (DESIGN §9 *Post-
    # work conformance*). Bounds the loop in `_settle_subtask` that re-spawns
    # the conformer when its output is malformed or residuals remain.
    # Exhausting this cap is a *warning*, not a failure — the phase is
    # advisory and never produces a `failed` / `blocked` subtask status.
    "conformance_rounds": 3,
    # Concurrent orchestrator-run build/lint/test measurements (DESIGN §6
    # *Memory containment*). Distinct from `max_parallel`, which bounds
    # WORKERS: a worker is spawned through `_await_worker_memory_admission`
    # and enrolled in a cgroup, while a BLT command `_run_streaming` starts is
    # neither — it is an orchestrator child with no `memory.max` and no
    # `pids.max` of its own. `scoped` mode makes each measurement small
    # (~seconds, a couple of test files), but `--subtask-tests full` puts a
    # whole suite behind every subtask, and `max_parallel` of those at once is
    # the shape that saturated a worker cgroup badly enough to raise
    # `worker_pids_max` to 2048. 2 is a deliberate floor rather than a
    # measured optimum: enough to overlap a slow axis with a fast one, low
    # enough that the uncontained case cannot multiply.
    "blt_parallel": 2,
    # Implementer completeness re-drives per subtask (DESIGN §9 *The one
    # gating axis: solution completeness*). Bounds the loop in
    # `_settle_subtask` that re-drives the implementer when the conformer's
    # gating `solution_defects` axis found concrete behavioral gaps in the
    # implementer's diff. A SEPARATE counter from conformance_rounds,
    # implementer_confidence_retries, failed_retries, and
    # subtask_continuations — the completeness loop must not silently consume
    # another budget (a self-graded axis that could borrow the confidence
    # budget is exactly the class of bug this change removes). Exhaustion is
    # *terminal*: the subtask returns `blocked` with the residual defects
    # named (fix + resume), never silently advisory. This is the
    # per-subtask analog of the plan-phase gates' die()-on-exhaustion, but
    # blocks a single subtask (partial-wave integration still proceeds,
    # DESIGN §3) rather than the whole run. Default 1: the found defects are
    # concrete and folded into the retry as mandatory criteria, so one
    # corrective pass is the intended budget; raise it for repos where the
    # implementer needs more attempts. Independent of --strict-conformer,
    # which governs only the advisory build/lint/test/residual axes.
    "completeness_retry_rounds": 1,
    # CRITIC-pattern mechanical-feedback re-invocation caps. Each worker
    # type gets code-enforced structural checks (file existence, graph
    # cycles, lockfile consistency, etc.) and the orchestrator re-invokes
    # with the check results as external feedback if issues are found.
    # Separate from conformance_rounds (which loops on observable
    # build/lint/test signals) and from confidence_rounds (which is
    # the worker-internal evidence-gate iteration budget).
    "judgment_check_rounds": 3,     # classifier, reconciler, provision,
                                    # overlap judge, integrator
    "planner_check_rounds": 3,      # planner (richer checks justify more)
    "implementer_confidence_retries": 2,  # separate from subtask_continuations
    "planner_samples": 3,           # multi-sample; set to 1 to disable
    "worker_timeout_sec": 5400,     # 90 minutes per worker process
    # If a worker emits no stdout events for this many seconds, log a
    # warning naming the worker, its PID, the elapsed silence, and any
    # stderr tail. Observation-only — does not kill the worker. The
    # wall-clock timeout (per-worker via TIMEOUT_DEFAULT_PER_WORKER, else
    # this 90-min cap) remains the only kill. Surfaces the
    # silent-hang failure class that otherwise gives the user zero
    # feedback between phase start and the 90-min hard kill.
    "worker_idle_warn_sec": 300,
    # Worker-internal evidence-gate iterations for planner and implementer
    # (DESIGN §8 + §13). User-tunable via --confidence-rounds /
    # LEERIE_CONFIDENCE_ROUNDS / leerie.toml; see IMPLEMENTATION.md §2
    # "Confidence rounds". The orchestrator does not count these iterations
    # — the cap is passed into each worker's prompt and the worker bounds
    # itself. Surfacing the knob is for tuning persistence, not for
    # promoting a prompt-governed limit to a code guarantee.
    "confidence_rounds": 8,
    # Per-worker cgroup memory cap (bytes). Each `claude -p` worker is
    # enrolled (by the cgroup broker — see scripts/cgroup-broker.py and
    # DESIGN §6, because the dropped-privilege orchestrator can't enroll
    # workers or set controller limits itself) in its own child
    # cgroup `leerie-w-<sid>` (run-scoped; see _cgroup_worker_sid) under
    # leerie.slice on both runtimes, and the
    # broker sets the cgroup's memory.max to this value. When a worker's tool
    # subtree (vitest, tsc, webpack workers, etc.) tries to allocate past
    # the cap, the kernel OOM-kills inside the cgroup — sshd / pid 1 /
    # other workers in the container are unaffected. This is the fix for
    # the OOM cascade from the finalmemoriam run (kernel ring on the
    # Colima VM showed agetty → journald → sshd → lima-guestagent killed
    # because a vitest worker blew past 1.85 GB RSS inside the
    # container's single memcg). Resolved at runtime by
    # resolve_worker_memory_max — CLI > env > leerie.toml > default. The
    # default value of None means "auto-derive from /proc/meminfo at run
    # start" (see _auto_worker_memory_max).
    "worker_memory_max_bytes": None,
    # Per-worker memory DEMAND estimate the two admission surfaces size on
    # (`_degrade_max_parallel_for_wave`, `_await_worker_memory_admission`).
    # Distinct from the ceiling above: that bounds one worker, this predicts
    # what one will use. None means "fall back to _WORKER_BUILD_PEAK_BYTES";
    # resolved at run start by resolve_worker_demand_estimate, which raises
    # it only for a repo declaring its own Node heap (N14-16).
    "worker_demand_estimate_bytes": None,
    # Whether the operator set the global wall-clock ceiling anywhere (N25).
    # Declared here for the same reason as the row above — it is resolved at
    # run start rather than configured — and because `resolve_worker_timeout`
    # keys the table bypass on it. False means "nothing was set, apply the
    # per-worker table"; the value cannot be derived from
    # `worker_timeout_sec` itself, since explicitly passing the default is
    # indistinguishable from passing nothing.
    "worker_timeout_explicit": False,
    # Per-worker cgroup v2 PID cap. Catches runaway fork-bomb behavior
    # from a worker's tool subtree while still admitting a legitimate
    # heavy conformance run. The prior default of 256 was too low for a
    # real workload: a repo whose full test suite fans out across many
    # subprocesses (e.g. leerie's own ~193-module suite, ~70 of which
    # shell out to bash harnesses / git / the launcher, run un-scoped by
    # the conformer per prompts/conformer.md) bursts past 256 in seconds
    # and wedges every subsequent fork with EAGAIN — the exact failure
    # the PID-exhaustion detector then reports. 1024 cleared that burst
    # while a runaway shell loop (in the thousands) still tripped the cap.
    # 1024 was in turn exhausted by a conformer that backgrounded a suite
    # run, lost track of its output file, and ran the full suite a second
    # time (pids.current=1024/1024, fork denials 221). Nothing in that
    # trace needed >1024 PIDs to do its work, so 2048 is slack against
    # that class of worker error rather than a re-derivation from the
    # workload — a genuine leak now issues twice as many forks before the
    # kernel starts refusing them here. Overridable per-repo via
    # resolve_worker_pids_max (CLI > env > leerie.toml > this default).
    "worker_pids_max": 2048,
    # Auth/quota backoff budget. When `claude -p` returns an envelope
    # whose `api_error_status` is 401/429/529 or whose result message
    # names an auth/rate-limit failure, `claude_p()` retries with tenacity's
    # `wait_exponential_jitter(initial=15, max=120, jitter=5)` until
    # this many cumulative seconds have elapsed, then bails with a
    # WorkerError that names the Claude Code subscription cap. 300 s
    # (~4 retries: 15 + 30 + 60 + 120 = 225 s plus jitter) is enough
    # to ride out a brief gateway hiccup but small enough that a real
    # 5-hour subscription cap surfaces to the user quickly rather than
    # tying the run up overnight. See IMPLEMENTATION.md §3 *Auth/quota
    # backoff* and §6 caps row.
    "auth_retry_max_sec": 300,
    # Per-subtask `claude -p` call multiplier consumed by
    # `check_budget_feasibility()` (DESIGN §13 *Budget feasibility —
    # fail fast at the cheapest moment*). Default 2.5 calibrated from
    # six on-disk runs as of 2026-06-03: three completed runs cluster
    # at 2.0–2.31 calls/subtask (1 implementer + ~1.3 conformer rounds);
    # one died-mid-execution run logged 2.59 with prompts/{implementer,
    # conformer}.md §"Environmental issues are out of scope" not yet
    # in effect (lint-fighting inflator). 2.5 covered the worst observed
    # real ratio before the per-subtask completeness gate; raised to 3.0
    # to absorb it (DESIGN §9 *The one gating axis: solution completeness*):
    # the conformer's `solution_defects` finding re-drives the implementer
    # up to `completeness_retry_rounds` times, so an N-subtask run can add
    # up to N extra implementer invocations that the preflight must foresee
    # or a large plan hits the max_total_workers backstop mid-wave. NOT a
    # runtime gate — consumed by the planner-output feasibility preflight
    # only, never by `bump_workers()`.
    "subtask_call_estimate": 3.0,
    # Multiplier applied to `total_estimate` inside
    # `check_budget_feasibility()` before comparison to
    # `max_total_workers`. With the default `subtask_call_estimate=3.0`,
    # the guaranteed cap headroom is ~1.20× — absorbs the observed worst
    # case plus one completeness re-drive per subtask while still flagging
    # the truly-unwinnable large runs that motivated the preflight.
    "budget_safety_margin": 1.15,
    # `claude -p` calls a RE-PLAN spends per already-known subtask, on top of
    # the planners themselves — consumed by `check_replan_affordable()` only,
    # never by `bump_workers()`. A re-plan re-runs the whole P1 decomposition,
    # not just the planners, which is the larger half: measured on run
    # `d8a764f3…` the re-plan issued 80 `fit_judge` + 5 `splitter` calls
    # against a subtask set that grew 35 → 65, i.e. ~1.3 decomposition calls
    # per subtask. Rounded up to 1.5 so the preflight errs toward declaring a
    # marginal re-plan unaffordable — the failure it exists to prevent (dying
    # mid-decomposition at the worker cap, having written no code) costs far
    # more than an early, actionable die() the operator answers with
    # `--max-workers`.
    "replan_decompose_estimate": 1.5,
    # Repo-map token budget for the personalized-PageRank-ranked subgraph
    # injected into the planner and splitter (DESIGN §5½ (P6) *Codebase structural
    # map*). The subgraph is binary-searched to fit within this many tokens;
    # ranked so the most task-relevant symbols appear at the prompt extremes.
    # ~1000 tokens keeps the injection below 5% of typical planner context.
    "repo_map_tokens": 1000,
    # Maximum recursion depth for _recursive_decompose() (DESIGN §5½ (P1) *P1
    # recursive judge + splitter*). A depth-5 tree can represent up to 2^5=32
    # leaves from a single subtask, more than enough for the observed 64-file
    # migration sweeps (target ~8 leaves). Terminates recursion at depth ≥ 5
    # even if fit_judge still scores below decompose_fit_threshold.
    "decompose_max_depth": 5,
    # P1 fit-judge pass threshold for _recursive_decompose() (DESIGN §5½ (P1)).
    # A subtask scoring ≥ this value is accepted as a leaf (well-fit).
    # MEASURED on n=24 telemetry-labeled subtasks: oversized mean 0.26 vs
    # well-fit mean 0.84 — 0.57 separation, 88% accuracy at 0.70. The
    # originally-planned 0.95 threshold over-splits 100% of well-fit subtasks
    # (their scores cluster at 0.82–0.93); 0.70 is the empirically-derived
    # optimum (see F1-build-measure.md).
    "decompose_fit_threshold": 0.70,
    # No-progress guard for _recursive_decompose(). If this many consecutive
    # recursion rounds produce no child whose fit score exceeds the parent's,
    # the subtask is accepted as a leaf with a warning rather than recursing
    # indefinitely. Prevents a degenerate splitter output from looping to
    # decompose_max_depth.
    "decompose_noprogress_rounds": 2,
    # Sub-file split span for _recursive_decompose() (DESIGN §5½ (P1) *Sub-file*).
    # A single-file subtask (or a single intra-file region) whose line span
    # exceeds this is split *within* the file — tier 1 on tree-sitter
    # function-boundary spans, tier 2 on contiguous line-windows for a function
    # that alone exceeds the cap. This is the un-covered mirror of the many-file
    # migration sweep: the whole-file splitter cannot break one dense file, so
    # such a subtask would otherwise be an unwinnable monolith (run 5d488583,
    # feat-005 — a 7041-line file failed 9 times). HEURISTIC, not
    # telemetry-calibrated like decompose_fit_threshold: anchored to that run's
    # measured span separation — the 1733-line executeStepWithHealing (25% of
    # the file, 34% of its edit sites) vs a largest-function span of ≤474 in
    # every sibling file. ~700 splits the giant into 2–3 windows and leaves a
    # normal function whole.
    "subfile_split_max_span": 700,
    # Floor on how often a given token's runway is re-probed (DESIGN §6
    # *Multi-token rotation*). Both the start-of-run selection and the
    # mid-run failover share one cache keyed by token fingerprint. Matches
    # the interval community tooling around the same undocumented usage
    # endpoint has independently converged on as safe against its
    # aggressive per-token rate limiting.
    "token_probe_cache_sec": 180,
}

# Every key the orchestrator writes to `st.data`. Canonical alongside the
# `state.json` field table in IMPLEMENTATION.md §8 — drift in either
# direction is caught by tests/test_state_fields.py.
STATE_FIELDS = (
    "task", "started_at", "finished_at",
    "waves", "completed_waves", "subtask_status",
    # Written by the LAUNCHER's `accept-blocked` mutator, not by this
    # module -- declared here because it is a state.json field and
    # STATE_FIELDS is the file's inventory.
    "accepted_blocked",
    "plan_snapshot",
    "decompose_snapshot",
    "blocked",
    "worker_count", "decompose_worker_count", "decompose_share", "telemetry",
    "categories", "classifier_questions", "prescribed_procedure",
    "required_items", "answers",
    # likely_already_satisfied / likely_already_satisfied_evidence:
    # optional, additive classifier-schema fields (DESIGN §8). Written by
    # phase_classify on every invocation (default False / ""); consulted by
    # phase_classification_gate on retry-loop exhaustion to route to the
    # cleared-but-empty terminal state instead of dying, when the
    # classifier's own investigation already found the task's deliverable
    # present on HEAD.
    "likely_already_satisfied", "likely_already_satisfied_evidence",
    "artifact_registry",
    "needs_source_of_truth", "source_of_truth_pref", "clarify",
    "dangerously_skip_permissions",
    "dangerously_force_strict_output",
    "skip_overlap_judge",
    "skip_adherence_check",
    "skip_coverage_check",
    "skip_completeness_check",
    "skip_integration_check",
    "skip_satisfied_check",
    "skip_budget_check",
    "strict_conformer",
    "subtask_tests",
    "skip_base_baseline",
    "skip_repo_map",
    # overlap_replan_done: set once when phase_overlap_judge responds to an
    # `unresolvable` collision with a scoped re-plan instead of dying
    # (DESIGN §5). Bounds that recovery to a single attempt — a second
    # unresolvable verdict after re-planning dies, since the contradiction
    # is then not something re-planning can resolve.
    "overlap_replan_done",
    # cgroup_containment: recorded by the fail-closed gate
    # (_enforce_and_record_cgroup_containment, in _run_phases just before the
    # first worker spawns) (DESIGN §6 *Memory containment*). {enforced: bool, hierarchy:
    # "v2"|"v1"|null}. `enforced=false` means workers ran without memory/PID
    # limits (only reachable via --dangerously-allow-uncapped). Persisted
    # because the crash that motivated the broker left NO artifact of the
    # silent containment failure — this makes it visible in state.json.
    "cgroup_containment",
    "verbosity", "inspect_dirs",
    "integrator_warnings", "scope_warnings",
    # Per-run memo of orchestrator-measured build/lint/test verdicts, keyed
    # by (axis, command, tree sha) — see `_measure_axes`. Deliberately placed
    # BEFORE `conformance` rather than between it and `unreviewed_subtasks`:
    # those two carry a documented adjacency pin (one records the review, the
    # other its absence) and must not be separated.
    "blt_results",
    "conformance",
    # Subtask ids whose conformer produced no result (crash / timeout), so a
    # subtask that was never reviewed is distinguishable from one that
    # passed. Adjacent to `conformance` because the two are only meaningful
    # together — see DESIGN §9.
    "unreviewed_subtasks",
    # sid -> check_symptom_evidence findings, for subtasks whose planner
    # entry declares `fixes_reported_symptom: true` (NOT a `bugfix-` id
    # prefix -- ids are re-homed by merges and synthesised for
    # verification-only work). Kept
    # beside the row above because both answer "what should the operator
    # know about a subtask that reports itself complete?" — see DESIGN §9
    # *A stale finding is not a bug*.
    "symptom_findings",
    "provision",
    # external_preconditions: planner-declared `extent: external` requires
    # entries collected during phase_reconcile (DESIGN §5
    # `requires.extent`). Persisted so _write_plan() can surface them in
    # plan.json's `preconditions` section. Empty list when no planner
    # declared any external requirement — the common case.
    "external_preconditions",
    # current_phase carries the orchestrator's active phase string so the
    # `_memory_sampler` (telemetry sidecar at memory.ndjson) can correlate
    # RSS growth with the code path that produced it. Updated at each
    # phase_* entry. Empty string before phase 1.
    "current_phase",
    # dropped_subtasks: subtasks soft-dropped by _filter_offtree_subtasks
    # because their files_likely_touched resolved off-tree (most commonly
    # into an inspect-dir mount). Map of sid → {reasons: [str], files:
    # [str]}. Empty/absent when no drop fired. Audit trail only — the
    # run proceeds with the surviving subtasks.
    "dropped_subtasks",
    # provider_subset_sids: sids flagged at plan time by
    # _warn_provider_subset_subtasks — every file the subtask expects to
    # touch is already owned by an ordered predecessor. Advisory, never a
    # drop, but read by _settle_subtask to probe the run branch BEFORE
    # spawning the implementer, since the redundancy usually only becomes
    # real once the predecessor commits. List of sid; empty when nothing
    # was flagged.
    "provider_subset_sids",
    # conditional_drops: planner-emitted consumer subtasks dropped by the
    # reconciler's `conditional_drops` resolution op (DESIGN §5) — i.e.
    # the planner authored the subtask as "no-op if X" and X turned out
    # to be unresolvable. Map of sid → {reason: str, from_unresolved_tag:
    # str}. Empty/absent when no conditional_drop fired. Distinct audit
    # field from `dropped_subtasks` (off-tree soft drops, phase 3) so the
    # two causes stay separately auditable.
    "conditional_drops",
    # speculative_collapse_drops: subtask sids mechanically pruned by
    # dead-subtask elimination (DESIGN §5) — fully-speculative subtasks
    # whose every in_plan requires was unresolvable because the provider
    # domain returned 0 subtasks. List of sid strings.
    "speculative_collapse_drops",
    # external_twin_demotions: unresolvable entries rescued by
    # _demote_unresolvable_with_external_twin (DESIGN §5 *The external
    # twin*) — a consumer declared a tag `in_plan` while another subtask
    # declared the same capability `extent: external`. Each item is
    # {sid, tag, match: "exact"|"singularized", twin_tag, twin_subtasks}.
    # Recorded so a wrong singularized pairing is auditable rather than
    # a silent reshaping of the dependency graph.
    "external_twin_demotions",
    # plan_overlap_judge / plan_overlap_applied: set by phase_overlap_judge
    # (DESIGN §5 *Cross-domain surface overlap*). plan_overlap_judge stores
    # the full judge worker output (list of collisions with a_sid/b_sid/
    # artifact/resolution/reason/merge_feasibility) for audit / replay
    # debugging. plan_overlap_applied stores the post-apply mutation summary
    # (each entry: {action: merge|drop_a|drop_b, surviving_sid, dropped_sid,
    # artifact}). Both empty/absent when the phase short-circuits
    # (single-planner runs, < 2 subtasks, --skip-overlap-judge) or when the
    # judge returned `{collisions: []}`.
    "plan_overlap_judge",
    "plan_overlap_applied",
    # duplicate_provider_merge_applied: set by phase_overlap_judge (M11
    # DECISION — DESIGN §5 *A deterministic floor underneath the judge*).
    # The post-apply mutation summary (same shape as plan_overlap_applied)
    # for merges the deterministic `check_duplicate_providers` floor
    # synthesized and applied via `_apply_overlap_collisions`, independent
    # of whether the `plan_overlap_judge` worker itself ran. Absent when
    # the floor found nothing to merge.
    "duplicate_provider_merge_applied",
    # adherence_gate: audit record from the phase 2⅞ instruction-adherence
    # gate (phase_adherence_gate) — {judge: <adherence_judge output>,
    # floor_issues: list[str]}. Written once the gate clears (immediately
    # or after re-planning). Absent when the gate cheap-skipped
    # (skip_adherence_check / no prescribed procedure) or the judge
    # crashed every round (degrade path returns without persisting this).
    "adherence_gate",
    # coverage_gate: audit record from the phase 2⅞½ task-coverage gate
    # (phase_planning_coverage_gate) — the final task_coverage_judge output
    # ({task_covered, coverage_gaps, rationale}). Written once, immediately
    # after the gate's single direct invocation — the gate is advisory and
    # never re-plans, so there are no rounds. Absent when that invocation
    # raised WorkerError or an OSError from process spawn (the degrade path
    # returns without persisting this).
    "coverage_gate",
    # classification_coverage_gate: audit record from phase_classification_gate
    # (DESIGN §8 *Independent adversarial verification*) — the final
    # classification_judge output. Absent when the judge crashed every round.
    "classification_coverage_gate",
    # wiring_gate: audit record from phase_wiring_gate (DESIGN §5 *A wiring
    # re-check on the fully-merged plan*, §8) — the final wiring_judge output.
    # Absent when the judge crashed every round.
    "wiring_gate",
    # integration_gate: per-sid audit record from integrate_wave's
    # integration_judge gate (DESIGN §8) — {sid: {defects, advisories,
    # merge_commit_sha, accepted}}. Written BEFORE die()ing (unlike
    # wiring_gate, which is written only on a clean pass) so a resume can
    # tell "not yet reviewed" (key absent) from "reviewed and rejected"
    # (`accepted: False`) from "reviewed and clean, or operator-accepted"
    # (`accepted: True`) — the `accept-integration <run-id> <sid>` verb
    # flips `accepted` to True. `integrate_wave` consults this key BEFORE
    # re-driving integrate.sh/the integrator: a present-and-not-accepted
    # entry re-invokes the judge directly against the already-committed
    # merge (integrate.sh alone would just see the branch already merged
    # and short-circuit past the judge entirely). Absent for a sid whose
    # merge never needed the integrator (no conflict — the judge only runs
    # post-integrator-merge).
    "integration_gate",
    # integration_defects: per-sid list[str] of the gating defect strings
    # from the most recent `integration_gate[sid]` entry that found a
    # behavioral defect — the record `accept-integration` marks accepted.
    # Mirrors `integration_gate[sid]["defects"]"` (kept as a separate,
    # flatter key per the parent subtask's audit-key contract) and is
    # popped once a re-invoked judge comes back clean. Absent when no sid
    # has ever had a gating defect.
    "integration_defects",
    # provision_recipe_gate: audit record from phase_provision_gate (DESIGN §8,
    # §6½) — the final provision_judge output. Absent when no recipe was
    # detected (kind:none) or the judge crashed every round.
    "provision_recipe_gate",
    # no_work_required / no_work_reasons: set by _finish_no_work_run when
    # every planner returns status="ready" with empty subtasks (DESIGN §8
    # *The cleared-but-empty terminal state*). The task is already
    # satisfied on HEAD; the orchestrator records finished_at, skips
    # phases 3-6, and exits 0. Absent on every normal run.
    "no_work_required",
    "no_work_reasons",
    # working_branch: the user's branch at the moment phase_classify
    # runs (`git rev-parse --abbrev-ref HEAD`). Mirrored to run.json
    # and to `<state-root>/runs/<id>/working-branch` (setup-run.sh writes
    # the on-disk copy later). Persisted into st.data so downstream
    # readers (pr_writer payload, _run_final_conformance's DIFF_BASE)
    # do not have to re-query git or re-read run.json.
    "working_branch",
    # pr_base_branch: the final branch this run's PR merges into. Defaults
    # to working_branch when the user does not override it via
    # --pr-base-branch / LEERIE_PR_BASE_BRANCH / leerie.toml. This is the
    # PR base ONLY — never the diff fork-point, which stays working_branch
    # (rev_range = working_branch..run_branch; final-conformance DIFF_BASE).
    # Overloading working_branch for both roles would corrupt the diff
    # base if the override branch isn't the actual fork point.
    "pr_base_branch",
    # leerie_version: the version string from .claude-plugin/plugin.json at
    # the time the run ORIGINALLY started — seeded once and immutable across
    # resumes (N38). A resume that rewrote it re-attributed the run's whole
    # event history to whatever release happened to be installed later, which
    # made pre-fix failures read as post-fix ones. The per-resume history
    # lives in `leerie_versions` below. Persisted so the PR footer can show
    # the exact version that produced the run, which aids debugging.
    "leerie_version",
    # leerie_commit: the short sha of $LEERIE_REPO's HEAD at run start, from
    # the launcher's LEERIE_COMMIT. None when leerie was installed from a
    # tarball rather than a checkout. Recorded because leerie_version alone
    # cannot attribute a run: plugin.json only moves on a `chore(release):`
    # commit while install.sh tracks `main`, so every run between releases
    # reports the same version whether or not it carries a given fix.
    "leerie_commit",
    # leerie_versions: append-only history of `{version, commit, at}`
    # snapshots, one per resume (plus one seeded at the original run start).
    # leerie_version/leerie_commit above are immutable across resumes by
    # design (N38) — a resume overwriting them with whatever is installed
    # NOW made a resumed run's failures read as attributable to the wrong
    # release. This list is where the "what was actually installed at each
    # resume" fact lives instead, without disturbing the original-run
    # attribution the other two fields exist for.
    "leerie_versions",
    # dep_capture_done: set to True in state.json and written as a sentinel
    # file (<run_dir>/dep_capture.done) after capture_repo_deps completes a
    # successful write. The run-start backstop checks the sentinel file to
    # skip runs already captured (idempotency).
    "dep_capture_done",
    # plans_after_*: per-planning-phase checkpoints (DESIGN §6 "Resumable
    # planning — a per-phase checkpoint cursor, not a `waves` gate"). Each
    # key holds the full `plans` list as it stood immediately after the
    # named phase completed and st.save()'d — never at phase entry (see
    # DESIGN's "current_phase alone is NOT a completion signal" warning).
    # `resume` walks this sequence in order and re-enters at the first
    # phase whose output key is absent, reusing the persisted `plans` as
    # that phase's input instead of re-deriving it. Absent for a phase
    # that has not yet completed (or on a run that has already reached
    # `waves`, since plan_snapshot/_write_plan supersede these by then).
    "plans_after_classify",
    "plans_after_plan",
    "plans_after_reconcile",
    "plans_after_overlap_judge",
    "plans_after_adherence_gate",
    "plans_after_coverage_gate",
    "plans_after_filters",
    # satisfied_probe_cache: per-subtask satisfied-probe verdicts (DESIGN
    # §6 "The satisfied-probe sweep needs finer-than-phase granularity"),
    # keyed by subtask id, persisted as each `probe_one` verdict returns
    # rather than only in aggregate after the whole sweep's `gather`
    # completes. Each entry also records the base commit sha at probe
    # time; a cached verdict whose sha no longer matches HEAD on resume is
    # treated as absent and the subtask is re-probed (correctness-critical
    # — the base tree can move between a pause and a resume, e.g. a
    # sibling run merging its own PR). A probe that crashes (`WorkerError`)
    # is deliberately never cached — no verdict was actually reached.
    "satisfied_probe_cache",
    # active_oauth_token: the raw CLAUDE_CODE_OAUTH_TOKEN value currently
    # selected for this run's `claude -p` spawns (DESIGN §6 *Multi-token
    # rotation*). Set by the start-of-run probe/ranking sweep when
    # CLAUDE_CODE_OAUTH_TOKENS is present, and mutated by claude_p's
    # mid-run failover on a rate-limited active token. Absent/None when
    # only the singular CLAUDE_CODE_OAUTH_TOKEN is in play (no rotation).
    # NEVER written to calls.ndjson, run.json, or any log line — only its
    # fingerprint (_token_fingerprint) is ever surfaced outside state.json.
    "active_oauth_token",
)

CATEGORIES = [
    "feature-implementation", "bug-fixing", "refactoring",
    "performance-optimization", "testing", "dependency-migration",
    "configuration-build", "infrastructure", "documentation",
]

# Short abbreviations used in the run_id branch-name prefix (DESIGN §6
# "The run identifier"). Every entry in CATEGORIES must have an abbrev —
# enforced by tests/test_run_id.py::test_category_abbrev_coverage.
CATEGORY_ABBREV = {
    "feature-implementation": "feat",
    "bug-fixing": "bugfix",
    "refactoring": "refactor",
    "performance-optimization": "perf",
    "testing": "test",
    "dependency-migration": "deps",
    "configuration-build": "config",
    "infrastructure": "infra",
    "documentation": "docs",
}

# Paths an implementer (or conformer) may never write to. `.leerie/`
# inside a worktree and `.git/` are coordination-only — leerie's own
# in-repo coordination subtree (e.g., `.leerie-setup.sh` lives at the
# repo root, but the directory `.leerie/` is reserved) and the git
# plumbing dir, respectively; neither is the implementer's surface.
# (Run state itself lives at `<state-root>` outside the repo, mounted at
# `/leerie-state` — see resolve_leerie_root.) Inside `.claude/`, the
# three documented user-deliverable subtrees are exempt
# (`agents/`, `commands/`, `skills/`) because they ARE legitimate
# deliverables — leerie's own self-healing skill, for instance, instructs
# consumers to write a subagent file at `.claude/agents/<name>.md`.
# Top-level `.claude/` files (`settings.json`, `settings.local.json`,
# any future per-session state) stay protected — they are coordination
# and config, not deliverable customizations. See DESIGN §9.
_PROTECTED_PREFIXES = (".leerie/", ".git/")
_CLAUDE_DELIVERABLE_PREFIXES = (
    ".claude/agents/", ".claude/commands/", ".claude/skills/",
)


def _is_protected_path(path: str) -> bool:
    """Return True if `path` is a meta-directory the implementer must not
    write to. See `_PROTECTED_PREFIXES` and `_CLAUDE_DELIVERABLE_PREFIXES`
    for the rule."""
    if any(path.startswith(p) for p in _PROTECTED_PREFIXES):
        return True
    if path.startswith(".claude/"):
        return not any(path.startswith(p) for p in _CLAUDE_DELIVERABLE_PREFIXES)
    return False

_READ_BASE = "Read,Grep,Glob,WebSearch,WebFetch"
# INSPECT_TOOLS is the read-only-with-shell bucket for classifier, planner,
# and reconciler. These workers run in the real repo cwd (not a worktree),
# so the default is that they cannot use --dangerously-skip-permissions.
# Without pre-approval, Bash calls in -p mode are gated by the permission
# system, return is_error=true, and surface as "tool-fail" — even for
# benign commands like `ls foo 2>&1` whose redirection trips the
# multiple-operations splitter. The Bash(<verb>:*) prefix patterns
# pre-approve specific read-only verbs (verified against claude 2.1.150:
# the pattern matcher handles trailing redirection like `2>&1`).
# Write/Edit are deliberately omitted: by default, the §12 "read-only
# worker" contract stays mechanically enforced — anything outside this
# allowlist falls through and is rejected in non-interactive mode. The
# top-level `leerie --dangerously-skip-permissions` flag (DESIGN §12 last
# paragraph) is the documented escape hatch: when set, claude_p passes
# --dangerously-skip-permissions to every worker, including the inspect
# bucket; the allowlist still names what the worker can call without
# prompting, but the gate that rejects everything else is lifted.
#
# Tool restriction is two-layered:
#   --allowedTools  (soft) — pre-approves tools for auto-execution;
#       bypassed entirely by --dangerously-skip-permissions.
#   --disallowedTools (hard, DISALLOWED_TOOLS) — removes tools from the
#       model's context; survives --dangerously-skip-permissions.
INSPECT_TOOLS = (
    f"{_READ_BASE},"
    "Bash(ls:*),Bash(find:*),Bash(cat:*),Bash(head:*),Bash(tail:*),"
    "Bash(wc:*),Bash(grep:*),Bash(rg:*),Bash(file:*),Bash(stat:*),"
    "Bash(tree:*),Bash(pwd),Bash(echo:*),"
    "Bash(git log:*),Bash(git show:*),Bash(git diff:*),"
    "Bash(git status:*),Bash(git branch:*),Bash(git ls-files:*)"
)
ACT_TOOLS = f"{_READ_BASE},Bash,Write,Edit"

# SATISFIED_PROBE_TOOLS — a deliberately narrow, BASE-TREE-ONLY subset of
# INSPECT_TOOLS for the phase-3 satisfied-probe (DESIGN §8 *Already-
# satisfied subtask elimination*). It must NOT include history-spanning
# git verbs (`git log:*`, `git show:*` with an arbitrary ref, `git
# branch`): a git worktree shares the main repo's full ref/object DB, so
# a probe that can reach other branches / later commits will "find" a
# deliverable that exists only on some OTHER branch and false-positive —
# silently dropping real work. Calibration measured 12/12 false-positives
# with full INSPECT_TOOLS latitude and 0 when scoped to the base tree.
# Only `git show HEAD:<path>`, `git diff`, and `git status` on the current
# checkout are allowed; the prompt reinforces the same rule (§12: the code
# constraint is the guarantee, the prompt is documentation).
#
# Every verb carries the `:*` trailing-wildcard suffix. A bare `Bash(verb)`
# is an EXACT-STRING match per the Claude Code permission docs ("Bash(npm run
# build) matches the exact command npm run build"), so `Bash(git status)`
# would permit only the literal zero-argument `git status` and deny every
# real invocation (`git status --porcelain=v1`, `--short`, …). The probe then
# burns its `claude -p` call, gets "requires approval", and reasons from
# partial evidence. `Bash(pwd)` is the one deliberate exception: it takes no
# arguments. (`git -C <dir> status` and compound `a && b` commands remain
# denied by design — the pattern is prefix-anchored and each subcommand of a
# compound must match independently.)
SATISFIED_PROBE_TOOLS = (
    f"{_READ_BASE},"
    "Bash(ls:*),Bash(cat:*),Bash(head:*),Bash(wc:*),Bash(grep:*),"
    "Bash(rg:*),Bash(file:*),Bash(stat:*),Bash(pwd),Bash(echo:*),"
    "Bash(git show HEAD:*),Bash(git diff:*),Bash(git status:*)"
)

# DISALLOWED_TOOLS is the hard-deny list passed via --disallowedTools to
# every worker.  Unlike --allowedTools (permission-tier only, bypassed by
# --dangerously-skip-permissions), --disallowedTools with bare tool names
# removes tools from the model's context entirely — the model cannot see
# or call them regardless of permission mode.  This prevents workers from
# spawning subagents, setting timers, or sending messages that the
# orchestrator cannot track.
DISALLOWED_TOOLS = (
    "Agent,SendMessage,"
    "ScheduleWakeup,"
    "CronCreate,CronDelete,CronList,"
    "RemoteTrigger,PushNotification"
)

# --inspect-dir preference: extra directories to grant the inspect-bucket
# workers (classifier, planner, reconciler, plan_overlap_judge, provision) read access to via the
# Claude Code CLI's --add-dir flag. Without this, Read/Grep/Glob and the
# allowlisted Bash verbs in INSPECT_TOOLS are sandboxed to the repo cwd,
# so cross-repo references like "~/src/enric/beacon" fail with "blocked,
# outside allowed working directories". Repeatable on the CLI; env var is
# colon-separated; TOML key is a comma-separated string. Empty by default.
INSPECT_DIRS_ENV = "LEERIE_INSPECT_DIRS"
INSPECT_DIRS_FILE = "leerie.toml"

EXIT_NEEDS_ANSWERS = 10   # emitted when clarification is needed but no TTY
# Emitted by `check_budget_feasibility()` (DESIGN §13 *Budget feasibility —
# fail fast at the cheapest moment*) when the estimated remaining `claude -p`
# calls plus the already-spent count exceeds `max_total_workers`. Distinct
# from EXIT_NEEDS_ANSWERS=10 (deferred clarification) and from generic
# `die()` exit code 1 so the Fly runtime's decide_teardown trap and
# automation around it can route this case specifically. The error message
# names a recommended `--max-workers` value. Not resumable: `resume`
# re-enters past _schedule(), so the preflight has nothing to gate; a run
# that died here re-runs from scratch with the recommended cap or a split
# task.
EXIT_BUDGET_INFEASIBLE = 11

# Emitted when State.__init__ cannot acquire the run-directory flock
# because another orchestrator already owns this run. Lets the launcher
# refuse `resume` cleanly when an orchestrator is still alive,
# instead of silently spawning a second one that would race on
# state.json (DESIGN §6 *Single owner per run dir*). 75 aligns with
# the BSD sysexits.h EX_TEMPFAIL convention.
EXIT_LOCKED = 75

# Fixed backoff before auto-resuming a rate-limit that carried NO parseable
# reset time — chiefly the out-of-credits mid-stream kill, where the kill left
# no `resetsAt` to compute a wake time from (DESIGN §6 *Rate-limited →
# auto-resume*). We can't know when credits/limits refresh, so we poll: sleep a
# short fixed interval and re-exec `resume`. A premature retry (still limited)
# just re-hits the same clean pause and sleeps again — cheap, and bounded by the
# persisted `max_total_workers` budget so a stuck run never runs away.
RATE_LIMIT_RETRY_BACKOFF_SEC = 300  # 5 minutes

# N30: minimum fraction of the state-dir filesystem's total capacity that
# must remain free. Below this, leerie refuses to start (preflight) or
# pauses resumably (mid-run).
#
# A proportional fraction, and deliberately the ONLY rule. A per-worktree
# measured bound was built on top of this and was wrong four separate ways
# before being withdrawn — see IMPLEMENTATION.md's "Disk headroom (N30)"
# section for what was tried and why each attempt failed. A fraction scales
# with disk size (a huge disk and a tiny one both keep a proportional
# margin) without pretending to know per-run byte cost, which is the
# quantity that proved unmeasurable from inside the orchestrator.
DISK_MIN_FREE_RATIO = 0.05  # 5% free

